PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId ?investorName ?score WHERE {
  ?inv rdf:type wm:Investor .
  ?inv wm:investorId ?investorId .
  OPTIONAL { ?inv wm:investorName ?investorName . }

  {
    SELECT ?investorId (MAX(xsd:decimal(?riskScore)) AS ?riskScore) (MAX(xsd:decimal(?liquidityScore)) AS ?liquidityScore)
    WHERE {
      ?ph rdf:type wm:PortfolioHealth .
      ?ph wm:investorId ?investorId .
      ?ph wm:riskScore ?riskScore .
      ?ph wm:liquidityScore ?liquidityScore .
    } GROUP BY ?investorId
  }

  {
    SELECT ?investorId (SUM(xsd:decimal(?allocPct)) AS ?allocConcentration)
    WHERE {
      ?sa rdf:type wm:SectorAllocation .
      ?sa wm:investorId ?investorId .
      ?sa wm:allocationPct ?allocPct .
    } GROUP BY ?investorId
  }

  {
    SELECT ?investorId (AVG(xsd:decimal(?volatility)) AS ?goalVolatility)
    WHERE {
      ?ig rdf:type wm:InvestmentGoal .
      ?ig wm:investorId ?investorId .
      ?ig wm:avgVolatilityPct ?volatility .
    } GROUP BY ?investorId
  }

  {
    SELECT ?investorId (MAX(xsd:decimal(?newAlloc) - xsd:decimal(?currAlloc)) AS ?scenarioChange)
    WHERE {
      ?sr rdf:type wm:ScenarioRebalancing .
      ?sr wm:investorId ?investorId .
      ?sr wm:newAllocationPct ?newAlloc .
      ?sr wm:currentAllocationPct ?currAlloc .
    } GROUP BY ?investorId
  }

  BIND( (COALESCE(?riskScore, 0) + COALESCE(?allocConcentration, 0) + COALESCE(?goalVolatility, 0) - COALESCE(?liquidityScore, 0) + COALESCE(?scenarioChange, 0)) AS ?score )
}
ORDER BY DESC(?score)
LIMIT 10

