PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?inv ?investorName ( ?score AS ?riskPressureScore )
WHERE {
  # Investor
  ?inv rdf:type wm:Investor ;
       wm:investorName ?investorName .

  # PortfolioHealth
  ?ph wm:healthOfInvestor ?inv ;
      wm:riskScore ?riskScore ;
      wm:liquidityScore ?liquidityScore .

  # Aggregated SectorAllocation (allocation concentration)
  {
    SELECT ?inv (SUM(xsd:decimal(?allocPct)) AS ?allocSum)
    WHERE {
      ?sa wm:allocationOfInvestor ?inv ;
          wm:allocationPct ?allocPct .
    }
    GROUP BY ?inv
  }

  # Aggregated InvestmentGoal (goal volatility)
