    SELECT ?inv (AVG(xsd:decimal(?volPct)) AS ?volAvg)
    WHERE {
      ?ig wm:belongsToInvestor ?inv ;
          wm:avgVolatilityPct ?volPct .
    }
    GROUP BY ?inv
  }

  # Aggregated ScenarioRebalancing (scenario change)
  {
    SELECT ?inv (SUM(xsd:decimal(?newAllocPct)) AS ?scenarioSum)
    WHERE {
      ?sr wm:scenarioRebalancingOfInvestor ?inv ;
          wm:newAllocationPct ?newAllocPct .
    }
    GROUP BY ?inv
  }

  # Compute the five‑table risk‑pressure score
  BIND ( ( xsd:decimal(?riskScore)
           + xsd:decimal(?allocSum)
           + xsd:decimal(?volAvg)
           - xsd:decimal(?liquidityScore)
           + xsd:decimal(?scenarioSum) ) AS ?score )
}
ORDER BY DESC(?score) ?inv
LIMIT 10

