          wm:investorId ?investorId ;
          wm:scenarioRebalanceId ?srId .
    }
    GROUP BY ?investorId
  }

  # Average riskScore and goalMatchPct per investor from PortfolioHealth
  {
    SELECT ?investorId (AVG(xsd:decimal(?risk)) AS ?average_risk_score) (AVG(xsd:decimal(?goal)) AS ?average_goal_match_pct)
    WHERE {
