PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?investorId ?investorName
WHERE {
  {
    SELECT ?investor ?investorId
    WHERE {
      ?investor rdf:type wm:Investor .
      ?investor wm:investorId ?investorId .
      OPTIONAL {
        ?investor wm:riskTolerance ?rtLit .
        BIND(LCASE(STR(?rtLit)) AS ?rtLow)
      }
      OPTIONAL {
        ?investor wm:hasRiskTolerance ?rtNode .
        ?rtNode rdfs:label ?rtLabel .
        BIND(LCASE(STR(?rtLabel)) AS ?rtLow)
      }
      FILTER(BOUND(?rtLow) && CONTAINS(?rtLow, "conservative"))
    }
  }
  ?investor wm:hasPortfolioHealth ?ph .
  ?ph rdf:type wm:PortfolioHealth .
  ?ph wm:riskScore ?riskScore .
  FILTER(xsd:decimal(?riskScore) < 35)

  ?investor wm:hasHolding ?holding .
  ?holding rdf:type wm:PortfolioHolding .
  ?holding wm:investmentName ?invName .
  FILTER(CONTAINS(LCASE(STR(?invName)), "gold"))

  OPTIONAL { ?investor wm:investorName ?investorName . }
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?logic ?scenario (COUNT(DISTINCT ?investor) AS ?investorCount)
WHERE {
  {
    SELECT DISTINCT ?investor ?logic
    WHERE {
      ?ra rdf:type wm:RebalancingAction ;
          wm:logic ?logic ;
          wm:rebalancingActionOfInvestor ?investor .
      ?investor rdf:type wm:Investor .
    }
  }
  {
    SELECT DISTINCT ?investor ?scenario
    WHERE {
      ?sr rdf:type wm:ScenarioRebalancing ;
          wm:scenario ?scenario ;
          wm:scenarioRebalancingOfInvestor ?investor .
      ?investor rdf:type wm:Investor .
    }
  }
}
GROUP BY ?logic ?scenario

