PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?category
       (SUM(xsd:decimal(COALESCE(?holdingSum, "0"))) AS ?totalHoldingValue)
       (SUM(xsd:decimal(COALESCE(?allocationSum, "0"))) AS ?totalSectorAllocation)
       (SUM(xsd:decimal(COALESCE(?cashSum, "0"))) AS ?totalCashFlowAmount)
WHERE {
  ?investor rdf:type wm:Investor .
  OPTIONAL { ?investor wm:category ?cat . }
  BIND(COALESCE(?cat, "NULL") AS ?category)

  # Aggregate holdings per investor
  OPTIONAL {
    SELECT ?investor (SUM(xsd:decimal(COALESCE(?holdingValue, "0"))) AS ?holdingSum)
    WHERE {
      ?investor wm:hasHolding ?holding .
      ?holding rdf:type wm:PortfolioHolding .
      OPTIONAL { ?holding wm:currentValue ?holdingValue . }
    }
    GROUP BY ?investor
  }

  # Aggregate sector allocations per investor
  OPTIONAL {
    SELECT ?investor (SUM(xsd:decimal(COALESCE(?allocValue, "0"))) AS ?allocationSum)
    WHERE {
      ?investor wm:hasSectorAllocation ?alloc .
      ?alloc rdf:type wm:SectorAllocation .
      OPTIONAL { ?alloc wm:totalInvestment ?allocValue . }
    }
    GROUP BY ?investor
  }

  # Aggregate cash flows per investor
  OPTIONAL {
    SELECT ?investor (SUM(xsd:decimal(COALESCE(?cashAmt, "0"))) AS ?cashSum)
    WHERE {
      ?investor wm:hasCashFlow ?cf .
      ?cf rdf:type wm:CashFlow .
      OPTIONAL { ?cf wm:amount ?cashAmt . }
    }
    GROUP BY ?investor
  }
}
GROUP BY ?category

