PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId ?investorName WHERE {
  {
    SELECT ?investorId (SUM(xsd:decimal(?sf)) AS ?totalShortfall) WHERE {
      ?goal rdf:type wm:InvestmentGoal .
      ?goal wm:shortfall ?sf .
      ?goal wm:belongsToInvestor ?invGoal .
      ?invGoal rdf:type wm:Investor .
      ?invGoal wm:investorId ?investorId .
    } GROUP BY ?investorId
    HAVING (SUM(xsd:decimal(?sf)) > 0)
  }
  {
    SELECT ?investorId (SUM(xsd:decimal(?amt)) AS ?totalCashFlow) WHERE {
      ?cf rdf:type wm:CashFlow .
      ?cf wm:amount ?amt .
      ?cf wm:cashFlowOfInvestor ?invCf .
      ?invCf rdf:type wm:Investor .
      ?invCf wm:investorId ?investorId .
    } GROUP BY ?investorId
    HAVING (SUM(xsd:decimal(?amt)) < 0)
  }
  {
    SELECT DISTINCT ?investorId WHERE {
      ?ra rdf:type wm:RebalancingAction .
      ?ra wm:action ?action .
      FILTER(CONTAINS(LCASE(STR(?action)), "de-risking"))
      ?ra wm:rebalancingActionOfInvestor ?invRa .
      ?invRa rdf:type wm:Investor .
      ?invRa wm:investorId ?investorId .
    }
  }
  ?investor rdf:type wm:Investor .
  ?investor wm:investorId ?investorId .
  OPTIONAL { ?investor wm:investorName ?investorName . }
}

